#define PI 3.14159265359

vec3 palette(float t, vec3 colA, vec3 colB, vec3 colC, vec3 colD) {
    return colA + colB * cos(2.0 * PI * (colC * t + colD));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    // Normalized pixel coordinates (from 0 to 1)
    //vec2 uv = fragCoord/iResolution.xy;
    vec2 uv = ((fragCoord.xy * 2.0) / iResolution.xy) - 1.0;
    //uv.xy = mod(uv.xy, abs(cos(iTime * 0.04)));
    uv.x *= clamp(sin(iTime * 0.25), 0.2, 1.0) * 4.0;
    uv.y *= clamp(cos(iTime * 0.5), 0.2, 1.0) * 2.0;


    // Time varying pixel color
    //vec3 col = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));

    vec3 ca = vec3(0.5, cos(iTime), 0.5);
    vec3 cb = vec3(0.5, 0.5, 0.5);
    vec3 cc = vec3(1.0, 0.4, 1.0);
    vec3 cd = vec3(0.00, 0.33, 0.67);

    uv.x *= cos(uv.x * 2.0 + sin(iTime));
    uv.y *= sin(uv.y * 2.0 + cos(iTime));

    vec3 col = palette(uv.x * 4.2 - uv.y * 8.0 + iTime, ca, cb, cc, cd);

    // Output to screen
    fragColor = vec4(col,1.0);
}
